// with order fields injected as a single "order" object to prevent global namespace pollution,
// and returns the resulting discount amount.
func CalculateDiscount(script string, order map[string]interface{}) (float64, error) {
	vm := goja.New()

	// Set a timeout context to prevent infinite loops
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	// Inject the entire order as a single object to prevent global namespace pollution
	// and avoid potential security issues with overwriting built-in globals.
	err := vm.Set("order", order)
