	wrappedScript := fmt.Sprintf(`
		(function() {
			%s
		})()
	`, script)

	// Execute the wrapped script with timeout protection
	var result goja.Value
	var execErr error

	done := make(chan struct{})
	go func() {
		result, execErr = vm.RunString(wrappedScript)
		close(done)
	}()

	select {
	case <-done:
		if execErr != nil {
			return 0.0, fmt.Errorf("script execution error: %w", execErr)
		}
	case <-ctx.Done():
		return 0.0, fmt.Errorf("script execution timed out (possible infinite loop)")
	}

	// Convert result to float64
	if result == nil {
		return 0.0, fmt.Errorf("script must return a number, got <nil>")
	}

	exported := result.Export()
	if exported == nil {
		return 0.0, fmt.Errorf("script must return a number, got <nil>")
	}

	discount, ok := exported.(float64)
	if !ok {
		// Try to convert from other numeric types (e.g., int, float32)
		switch v := exported.(type) {
		case int:
			discount = float64(v)
		case int32:
