        switch v := res.result.Export().(type) {
        case float64:
            discount = v
        case int:
            discount = float64(v)
        case int32:
            discount = float64(v)
        case int64:
            discount = float64(v)
        case float32:
            discount = float64(v)
        default:
            return 0.0, fmt.Errorf("script must return a number, got %T", res.result.Export())
