func CalculateDiscount(script string, order map[string]interface{}) (float64, error) {
	vm := goja.New()

	// Create a timeout to prevent infinite loops
	timer := time.AfterFunc(5*time.Second, func() {
		vm.Interrupt("script execution timeout")
	})
	defer timer.Stop()

	// Create an order object and set it as a global variable
	orderObj := vm.NewObject()
	for key, value := range order {
		err := orderObj.Set(key, value)
		if err != nil {
			return 0.0, fmt.Errorf("failed to set order property %s: %w", key, err)
		}
	}
	err := vm.Set("order", orderObj)
	if err != nil {
		return 0.0, fmt.Errorf("failed to set order object: %w", err)
	}

	// Execute the script
	result, err := vm.RunString(script)
	if err != nil {
		return 0.0, fmt.Errorf("script execution error: %w", err)
	}

	// Convert result to float64
	exported := result.Export()
	discount, ok := exported.(float64)
	if !ok {
		// Try to convert from other numeric types (e.g., int, float32)
		switch v := exported.(type) {
		case int:
			discount = float64(v)
		case int32:
			discount = float64(v)
		case int64:
			discount = float64(v)
		case float32:
			discount = float64(v)
		default:
			return 0.0, fmt.Errorf("script must return a number, got %T", exported)
		}
	}

	return discount, nil
}

